  medical: ["", "....####", "....####", "....####", ".##########", ".##########", ".##########", ".##########", "....####", "....####", "....####"],
  growth: [".....##", "....####", "...######", "..########", ".....##", ".....##", ".....##", ".....##", "", "##.##.##.##", "##.##.##.##"],
  locker: ["", ".##########", "############", "###.##.##.##", "############", ".##########", "..##", "..#"],
  scout: ["", "...####", "..#....#", ".#......#", ".#......#", ".#......#", ".#......#", "..#....#", "...####.#", "........##", ".........##", "..........##"],
  draft: [".....##", ".....##", "....####", "############", ".##########", "..########", "...######", "...######", "..###..###", "..##....##", ".##......##"],
  market: ["", "........#", "........##", ".##########", "........##", "........#", "...#", "..##", ".##########", "..##", "...#"],
  cap: [".....#", "...#####", "..##.#", "..##.#", "...####", ".....###", ".....#.##", ".....#.##", "..######", ".....#"],
  club: ["", "..########", "..##.##.##", "..########", "..##.##.##", "..########", "..##.##.##", "..########", "..###..###", "..###..###", "############"],
  staff: ["....####", ".###....###", ".#........#", ".#.######.#", ".#........#", ".#.######.#", ".#........#", ".#.####...#", ".#........#", ".##########"],
